                Image(
                    painter = painterResource(R.drawable.normal_home_default_avatar_v2),
                    contentDescription = "ç™»å½•æˆ–æ³¨å†Œ",
                    contentScale = ContentScale.Fit,
                    modifier = guestModifier,
                )
            }
        }
    }
}

